    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            touches_edge = False
            while q:
                y, x = q.popleft()
                component.append((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == background and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if not touches_edge:
                for y, x in component:
                    out[y][x] = 4
    return out
